          },
        });

        // Create fund reward
        await tx.reward.create({
          data: {
            userId: message.userId,
            type: "CLUB_FUND",
            amount: amount * 0.1, // 10% bonus
            reason: `Club funding reward`,
          },
        });
      }
      break;

    case "poll":
      // Handle poll voting
