  const now = Date.now();
  const oneMinute = 60 * 1000;
  
  const record = rateLimitMap.get(identifier);
  
  if (!record || now > record.resetTime) {
    rateLimitMap.set(identifier, { count: 1, resetTime: now + oneMinute });
