async function handleInlineQuery(
  inlineQuery: z.infer<typeof TelegramInlineQuerySchema>
) {
  const queryId = inlineQuery.id;
  const query = inlineQuery.query.toLowerCase();
  const userId = inlineQuery.from.id;

  const results = [];

  // Поиск по запросу
  if (query.includes("swap") || query.includes("своп")) {
    results.push({
      type: "article",
      id: "swap_ton_ndt",
      title: "💱 Своп TON ↔ NDT",
      description: "Быстрый обмен TON на NDT и обратно",
      input_message_content: {
        message_text: `💱 *Своп TON ↔ NDT*\n\nОткройте DEX для обмена:`,
        parse_mode: "Markdown",
