  }

  if (query.includes("analytics") || query.includes("аналитика")) {
    results.push({
      type: "article",
      id: "analytics_dashboard",
      title: "📊 Аналитика DEX",
      description: "Просмотр рыночной аналитики и прогнозов",
      input_message_content: {
