import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { db } from '@/lib/db'
import { getServerSession } from 'next-auth/next'
import { authOptions } from '@/lib/auth'
import { trackContributionSchema } from '@/lib/schemas'
import { handleApiError } from '@/lib/errors/errorHandler'

// POST /api/tracks/[id]/contribute - Contribute to track progress
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params
    const session = await getServerSession(authOptions)
    
    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      )
    }

    const body = await request.json()
    const { amount, message } = trackContributionSchema.parse(body)

    // Find the track
    const track = await db.track.findUnique({
      where: { id },
      select: {
        id: true,
        title: true,
        artistId: true,
        progressTarget: true,
        progressCurrent: true,
        progressContributors: true,
        isProgressComplete: true,
        status: true
      }
    })

    if (!track) {
      return NextResponse.json(
        { error: 'Track not found' },
        { status: 404 }
      )
    }

    if (track.isProgressComplete) {
      return NextResponse.json(
        { error: 'Progress already complete' },
        { status: 400 }
      )
    }

    if (track.status !== 'DRAFT') {
