        });

        await db.user.update({
          where: { id: userId },
          data: { balance: { increment: 1 } },
        });
      }
    }

    return NextResponse.json({ message: "Play recorded successfully" });
  } catch (error) {
    console.error("Error recording play:", error);
    return NextResponse.json(
