'use client'

import { useState, useEffect, useRef, useCallback, useMemo } from 'react'
import { useSession } from 'next-auth/react'
import { Card, CardContent, CardDescription, CardHeader, CardTitle, Button, Input, Badge } from '@/components/ui'
import { 
  Search, 
  Filter, 
  Play, 
  Clock, 
  Heart, 
  TrendingUp,
  Grid,
  List,
  Music,
  Users,
  Calendar
} from '@/components/icons'
import { TrackCard } from '@/components/audio/track-card'
import { formatNumber, formatTime } from '@/lib/utils'
import { FixedSizeList as VirtualList } from 'react-window'

interface Track {
  id: string
  title: string
  artistName: string
  genre: string
  duration: number
  playCount: number
  likeCount: number
  ipfsHash: string
  audioUrl: string
  coverImage: string
  isExplicit: boolean
  isPublished: boolean
  createdAt: string
  updatedAt: string
  artist: {
    id: string
    username: string
    displayName: string
    avatar: string
  }
}

interface FilterOptions {
  search: string
  genre: string
  sortBy: 'createdAt' | 'playCount' | 'likeCount'
  sortOrder: 'asc' | 'desc'
  viewMode: 'grid' | 'list'
}

export default function TracksPage() {
  const { data: session, status } = useSession()
  const [tracks, setTracks] = useState<Track[]>([])
  const [loading, setLoading] = useState(true)
  const [filters, setFilters] = useState<FilterOptions>({
    search: '',
    genre: '',
    sortBy: 'createdAt',
    sortOrder: 'desc',
    viewMode: 'grid'
  })

  useEffect(() => {
    fetchTracks()
  }, [filters])

  // Мемоизируем функцию fetchTracks для предотвращения лишних ререндеров
  const fetchTracks = useCallback(async () => {
    try {
      setLoading(true)
      const params = new URLSearchParams({
        search: filters.search,
        genre: filters.genre,
        sortBy: filters.sortBy,
        sortOrder: filters.sortOrder
      })

      const response = await fetch(`/api/tracks?${params}`)
      if (response.ok) {
        const data = await response.json()
        setTracks(data.tracks)
      }
    } catch (error) {
      console.error('Error fetching tracks:', error)
    } finally {
      setLoading(false)
    }
  }, [filters]) // Добавляем зависимость filters для корректной работы useCallback

  const handleSearch = (value: string) => {
    setFilters(prev => ({ ...prev, search: value }))
  }

  const handleGenreFilter = (genre: string) => {
    setFilters(prev => ({ ...prev, genre }))
  }

  const handleSort = (sortBy: 'createdAt' | 'playCount' | 'likeCount') => {
    setFilters(prev => ({ 
      ...prev, 
      sortBy,
      sortOrder: prev.sortBy === sortBy && prev.sortOrder === 'desc' ? 'asc' : 'desc'
    }))
  }

  const toggleViewMode = () => {
    setFilters(prev => ({ 
      ...prev, 
      viewMode: prev.viewMode === 'grid' ? 'list' : 'grid'
    }))
  }

  // Мемоизируем отфильтрованные треки для предотвращения повторных вычислений при ререндере
  const filteredTracks = useMemo(() => {
    if (!tracks.length) return [];
    
    // Фильтрация по поиску
    let result = tracks;
    if (filters.search) {
      const searchLower = filters.search.toLowerCase();
      result = result.filter(track => 
        track.title.toLowerCase().includes(searchLower) || 
        track.artistName.toLowerCase().includes(searchLower)
      );
    }
    
    // Фильтрация по жанру
    if (filters.genre) {
      result = result.filter(track => track.genre === filters.genre);
    }
    
    // Сортировка
    return [...result].sort((a, b) => {
      const aValue = a[filters.sortBy];
      const bValue = b[filters.sortBy];
      
      if (filters.sortOrder === 'asc') {
        return aValue > bValue ? 1 : -1;
      } else {
        return aValue < bValue ? 1 : -1;
      }
    });
  }, [tracks, filters]);

  const genres = [
    'Все жанры',
    'Pop',
    'Rock',
    'Hip-Hop',
    'Electronic',
    'Jazz',
    'Classical',
    'R&B',
    'Country',
    'Folk'
  ]

  if (status === 'loading') {
    return (
      <div className="container mx-auto px-4 py-8">
        <div className="animate-pulse space-y-4">
          <div className="h-8 bg-muted rounded w-1/3"></div>
          <div className="h-4 bg-muted rounded w-1/2"></div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {[...Array(4)].map((_, i) => (
              <div key={i} className="h-32 bg-muted rounded-lg"></div>
            ))}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="container mx-auto px-4 py-8">
      {/* Header */}
      <div className="mb-8">
        <div className="flex items-center justify-between mb-6">
          <div>
            <h1 className="text-3xl font-bold mb-2">Музыкальные треки</h1>
            <p className="text-muted-foreground">
              Исследуйте и слушайте музыку от артистов NormalDance
            </p>
          </div>
          <Button variant="outline" onClick={toggleViewMode}>
            {filters.viewMode === 'grid' ? (
              <>
                <List className="h-4 w-4 mr-2" />
                Список
              </>
            ) : (
              <>
                <Grid className="h-4 w-4 mr-2" />
                Сетка
              </>
            )}
          </Button>
        </div>

        {/* Search and Filters */}
        <div className="flex flex-col md:flex-row gap-4">
          <div className="relative flex-1">
