"use client";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { useTelegram } from "@/contexts/telegram-context";
import { useToast } from "@/hooks/use-toast";
import { getAIRecommendationEngine } from "@/lib/ai-recommendations";
import {
  Brain,
  Heart,
  Music,
  RefreshCw,
  Share2,
  Sparkles,
  Users,
} from "lucide-react";
import { useCallback, useEffect, useRef, useState } from "react";

interface RecommendationDisplay {
  id: string;
  title: string;
  artist: string;
  genre: string;
  duration: number;
  score: number;
  confidence: number;
  type: "personal" | "trending" | "discovery" | "social";
  explanations: string[];
  audioFeatures: {
    hasVocals: boolean;
    isLive: boolean;
    isAcoustic: boolean;
  };
  socialFeatures: {
    likeCount: number;
    sharingCount: number;
    trendingScore: number;
  };
}

interface AIRecommendationsProps {
  userId: string;
  compact?: boolean;
  showFilters?: boolean;
  onTrackSelect?: (trackId: string) => void;
  onTrackPlay?: (trackId: string) => void;
  onTrackLike?: (trackId: string) => void;
  onTrackSkip?: (trackId: string) => void;
}

export function AIRecommendations({
  userId,
  compact = false,
  showFilters = false,
  onTrackSelect,
  onTrackPlay,
  onTrackLike,
  onTrackSkip,
}: AIRecommendationsProps) {
  const [recommendations, setRecommendations] = useState<
    RecommendationDisplay[]
  >([]);
  const [loading, setLoading] = useState(false);
  const [filters, setFilters] = useState({
    type: "all",
    count: 10,
    genre: "all",
    artist: "all",
  });

  const { isTMA } = useTelegram();
  const hapticFeedback = (type: string) => {
    // Пока используем простую реализацию, чтобы избежать ошибок типизации
    console.log(`Haptic feedback: ${type}`);
  };
  const { toast } = useToast();

  const engine = getAIRecommendationEngine();
  const refreshRef = useRef<NodeJS.Timeout | null>(null);

  // Load recommendations
  const loadRecommendations = useCallback(async () => {
    if (!userId) return;

    setLoading(true);
    try {
      const results = await engine.getRecommendations(userId, {
        count: filters.count,
        type: filters.type as
          | "all"
          | "personal"
          | "trending"
          | "discovery"
          | "social",
        filters: {
          genre: filters.genre !== "all" ? [filters.genre] : undefined,
          artist: filters.artist !== "all" ? [filters.artist] : undefined,
          minRating: 4.0,
          minDuration: 120,
          maxDuration: 600,
        },
      });

      // Format results for display
      const formattedRecommendations: RecommendationDisplay[] = results.map(
        (rec) => ({
          id: rec.track.id,
          title: rec.track.title,
          artist: rec.track.artist,
          genre: rec.track.genre,
          duration: rec.track.duration,
          score: rec.score,
          confidence: rec.confidence,
          type: rec.type,
          explanations: rec.explanations,
          audioFeatures: rec.track.audioFeatures,
          socialFeatures: rec.track.socialFeatures,
        })
      );

      setRecommendations(formattedRecommendations);
    } catch (error) {
      console.error("Failed to load recommendations:", error);
      toast({
        title: "Failed to load recommendations",
        description: "Please try again",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  }, [userId, filters, engine]);

  // Auto-refresh recommendations
  useEffect(() => {
    loadRecommendations();

    refreshRef.current = setTimeout(() => {
      loadRecommendations();
    }, 30000); // Refresh every 30 seconds

    return () => {
      if (refreshRef.current) clearTimeout(refreshRef.current);
    };
  }, [userId, filters]);

  const handleRefresh = async () => {
    await loadRecommendations();
    hapticFeedback("impact");

    toast({
      title: "Recommendations refreshed",
      description: "Updated with latest AI suggestions",
    });
  };

  const handleFilterChange = (newFilters: typeof filters) => {
    setFilters(filters);
  };

  const handleTrackAction = async (
    action: "play" | "like" | "skip",
    trackId: string
  ) => {
    hapticFeedback("selection");

    switch (action) {
      case "play":
        onTrackPlay?.(trackId);
        break;
      case "like":
        onTrackLike?.(trackId);
        // Add to liked tracks
        break;
      case "skip":
        onTrackSkip?.(trackId);
        // Add to skipped tracks
        break;
    }
  };

  const getTypeColor = (type: string): string => {
    switch (type) {
      case "personal":
        return "bg-blue-500 text-white";
      case "trending":
        return "bg-green-500 text-white";
      case "discovery":
        return "bg-purple-500 text-white";
      case "social":
        return "bg-orange-500 text-white";
      default:
        return "bg-gray-500 text-white";
    }
  };

  const getTypeLabel = (type: string): string => {
    switch (type) {
      case "personal":
        return "For You";
      case "trending":
        return "Trending";
      case "discovery":
        return "Discover";
      case "social":
        return "Popular";
      default:
        return "Recommended";
    }
  };

  const getTypeIcon = (type: string): string => {
    switch (type) {
      case "personal":
        return "🎯";
      case "trending":
        return "📈";
      case "discovery":
        return "🔍";
      case "social":
        return "👥";
      default:
        return "🎵";
    }
  };

  // Get type badge styling
  const getTypeBadge = (type: string) => {
    const colors = getTypeColor(type);
    return (
      <Badge className={colors}>
        {getTypeIcon(type)} {getTypeLabel(type)}
      </Badge>
    );
  };

  if (!userId) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Brain className="h-5 w-5" />
            AI Recommendations
          </CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-center text-muted-foreground py-8">
            Please log in to get personalized music recommendations powered by
            AI
          </p>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {!compact && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Brain className="h-5 w-5" />
              AI Recommendations
            </CardTitle>
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Button
                size="sm"
                variant="outline"
                onClick={handleRefresh}
                disabled={loading}
              >
                <RefreshCw className="h-4 w-4 mr-1" />
                {loading ? "Loading..." : "Refresh"}
              </Button>
            </div>
          </CardHeader>

          {showFilters && (
            <CardContent>
              <div className="flex flex-wrap gap-2 mb-4">
                <select
                  value={filters.type}
                  onChange={(e) =>
                    handleFilterChange({
                      ...filters,
                      type: e.target.value as
                        | "all"
                        | "personal"
                        | "trending"
                        | "discovery"
                        | "social",
                    })
                  }
