      case "discovery":
        return "bg-purple-500 text-white";
      case "social":
        return "bg-orange-500 text-white";
      default:
        return "bg-gray-500 text-white";
    }
  };

  const getTypeLabel = (type: string): string => {
    switch (type) {
      case "personal":
        return "For You";
      case "trending":
        return "Trending";
      case "discovery":
        return "Discover";
      case "social":
        return "Popular";
      default:
        return "Recommended";
    }
  };

  const getTypeIcon = (type: string): string => {
    switch (type) {
      case "personal":
        return "🎯";
      case "trending":
        return "📈";
      case "discovery":
        return "🔍";
      case "social":
        return "👥";
      default:
