'use client'

import { useState, useEffect, useRef } from 'react'
import { Card, CardContent, CardHeader, CardTitle, Button, Badge } from '@/components/ui'
import { 
  Play, 
  Pause, 
  Volume2, 
  VolumeX,
  Lock,
  Unlock,
  Shield,
  Download,
  Wifi,
  WifiOff,
  Smartphone,
  Monitor,
  Headphones,
  Music,
  Clock,
  Coins,
  Crown,
  Star,
  Award,
  Zap,
  Eye,
  EyeOff,
  AlertTriangle,
  CheckCircle,
  Info,
  Settings,
  Gift,
  CreditCard,
  Wallet,
  Key,
  Database,
  Globe,
  Smartphone as Phone,
  Laptop,
  Tablet
} from '@/components/icons'
import { cn } from '@/lib/utils'

interface PlaybackSession {
  id: string
  trackId: string
  startTime: number
  pausedTime?: number
  isBackground: boolean
  isOffline: boolean
  hasLicense: boolean
  deviceId: string
  walletAddress: string
}

interface NFTPass {
  id: string
  type: 'day' | 'track' | 'club' | 'genre' | 'olympic'
  name: string
  price: number
  duration: number // in hours
  description: string
  benefits: string[]
  icon: string
  color: string
  isActive: boolean
  expiresAt?: number
}

interface AntiPirateSystemProps {
  className?: string
}

export function AntiPirateSystem({ className }: AntiPirateSystemProps) {
  const [isPlaying, setIsPlaying] = useState(false)
  const [currentTrack, setCurrentTrack] = useState<any>(null)
  const [playbackSession, setPlaybackSession] = useState<PlaybackSession | null>(null)
  const [freeTracksUsed, setFreeTracksUsed] = useState(0)
  const [isBackground, setIsBackground] = useState(false)
  const [isOffline, setIsOffline] = useState(false)
  const [activePasses, setActivePasses] = useState<NFTPass[]>([])
  const [showPasses, setShowPasses] = useState(false)
  const [deviceId, setDeviceId] = useState('')
  const [walletAddress, setWalletAddress] = useState('')
  const audioRef = useRef<HTMLAudioElement>(null)

  // Mock data - в реальном приложении будет загружаться из API
  const availablePasses: NFTPass[] = [
    {
