'use client'

import { useState, useRef, useEffect, useCallback, useMemo } from 'react'
import { useAudioStore } from '@/store/use-audio-store'
import useNetworkStatus from '@/hooks/useNetworkStatus'
import { Button, Slider, Card, CardContent, Badge, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, Avatar, AvatarFallback, AvatarImage } from '@/components/ui'
import {
  Play,
  Pause,
  SkipBack,
  SkipForward,
  Volume2,
  VolumeX,
  Heart,
  Shuffle,
  Repeat,
  Settings,
  Equalizer,
  Waves,
  BarChart3,
  Playlist,
  TrendingUp,
  List,
  X,
  Crown,
  Clock,
  Headphones,
  Music,
  Mic,
  Square,
  Triangle,
  Zap,
  CheckCircle,
  Signal,
  SignalHigh,
  SignalMedium,
  SignalLow,
  Plus,
  Download,
  Save
} from '@/components/icons'
import { formatTime } from '@/lib/utils'
import { cn } from '@/lib/utils'
import { AudioVisualizer } from './audio-visualizer'
import { PlaylistManager } from './playlist-manager'

// Web Worker для обработки аудио
const audioWorker = new Worker(new URL('../../workers/audio-processor.worker.ts', import.meta.url))

interface AudioQuality {
  id: string
  name: string
  bitrate: number
  sampleRate: number
  extension: string
  size: string
  priority: number
}

interface EqualizerPreset {
  id: string
  name: string
  settings: {
    bass: number
    mid: number
    treble: number
    gain: number
  }
  icon: React.ReactNode
}

interface AudioCache {
  [key: string]: {
    audio: HTMLAudioElement
    lastUsed: number
    quality: string
  }
}

export function OptimizedAudioPlayer() {
  const {
    currentTrack,
    isPlaying,
    volume,
    isMuted,
    currentTime,
    duration,
    queue,
    currentQueueIndex,
    history,
    shuffle,
    repeat,
    play,
    pause,
    setVolume,
    toggleMute,
    seekTo,
    playNext,
    playPrevious,
    toggleLike,
    toggleShuffle,
    setRepeat,
    addToQueue,
    removeFromQueue,
    clearQueue,
    createPlaylist,
    addToPlaylist,
    removeFromPlaylist,
    getUserPlaylists,
    setCurrentPlaylist
  } = useAudioStore()

  const audioRef = useRef<HTMLAudioElement>(null)
  const { effectiveType } = useNetworkStatus()
  const [isLiked, setIsLiked] = useState(false)
  const [showQueue, setShowQueue] = useState(false)
  const [showVisualizer, setShowVisualizer] = useState(true)
  const [showPlaylistManager, setShowPlaylistManager] = useState(false)
  const [showStats, setShowStats] = useState(false)
  const [showQualitySettings, setShowQualitySettings] = useState(false)
  const [showEqualizer, setShowEqualizer] = useState(false)
  const [showAdvancedSettings, setShowAdvancedSettings] = useState(false)
  
  // Состояния для плейлистов
  const [playlists, setPlaylists] = useState<any[]>([])
  const [currentPlaylist, setCurrentPlaylistState] = useState<any>(null)
  const [newPlaylistName, setNewPlaylistName] = useState('')
  const [newPlaylistDescription, setNewPlaylistDescription] = useState('')
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedQuality, setSelectedQuality] = useState('auto')
  
  // Состояния для эквалайзера
  const [equalizerSettings, setEqualizerSettings] = useState({
    bass: 0,
    mid: 0,
    treble: 0,
    gain: 0
  })
  
  // Состояния для визуализации
  const [visualizerType, setVisualizerType] = useState<'bars' | 'wave' | 'circle' | 'particles'>('bars')
  const [visualizerColor, setVisualizerColor] = useState('#3b82f6')
  const [visualizerSensitivity, setVisualizerSensitivity] = useState(50)
  
  // Кэш аудио
  const [audioCache, setAudioCache] = useState<AudioCache>({})
  const [isPreloading, setIsPreloading] = useState(false)
  const [preloadProgress, setPreloadProgress] = useState(0)
  
  // Качество звука с приоритетами
  const audioQualities: AudioQuality[] = useMemo(() => [
    { id: 'low', name: 'Низкое (64 kbps)', bitrate: 64, sampleRate: 22050, extension: 'mp3', size: '2-5 MB', priority: 1 },
    { id: 'medium', name: 'Среднее (128 kbps)', bitrate: 128, sampleRate: 44100, extension: 'mp3', size: '4-10 MB', priority: 2 },
    { id: 'high', name: 'Высокое (320 kbps)', bitrate: 320, sampleRate: 48000, extension: 'mp3', size: '8-15 MB', priority: 3 },
    { id: 'lossless', name: 'Lossless (FLAC)', bitrate: 1411, sampleRate: 96000, extension: 'flac', size: '20-40 MB', priority: 4 },
    { id: 'auto', name: 'Авто (адаптивное)', bitrate: 0, sampleRate: 0, extension: 'mp3', size: 'Переменное', priority: 0 }
  ], [])
  
  // Пресеты эквалайзера
  const equalizerPresets: EqualizerPreset[] = useMemo(() => [
    {
      id: 'flat',
      name: 'Плоский',
      settings: { bass: 0, mid: 0, treble: 0, gain: 0 },
      icon: <Square className="h-4 w-4" />
    },
    {
      id: 'bass_boost',
      name: 'Усиление баса',
      settings: { bass: 8, mid: 0, treble: -2, gain: 2 },
      icon: <Triangle className="h-4 w-4" />
    },
    {
      id: 'vocal_boost',
      name: 'Усиление вокала',
      settings: { bass: -2, mid: 6, treble: 2, gain: 0 },
      icon: <Mic className="h-4 w-4" />
    },
    {
      id: 'rock',
      name: 'Рок',
      settings: { bass: 5, mid: 2, treble: 5, gain: 3 },
      icon: <Zap className="h-4 w-4" />
    },
    {
      id: 'jazz',
      name: 'Джаз',
      settings: { bass: 3, mid: 3, treble: 2, gain: 1 },
      icon: <Music className="h-4 w-4" />
    },
    {
      id: 'classical',
      name: 'Классика',
      settings: { bass: 2, mid: 4, treble: 4, gain: 2 },
      icon: <Crown className="h-4 w-4" />
    }
  ], [])

  // Оптимизированная функция получения URL аудио
  const audioSrc = useCallback(() => {
    if (!currentTrack) return ''
    
    // Определяем качество звука
    let quality = audioQualities.find(q => q.id === selectedQuality)
    if (!quality || selectedQuality === 'auto') {
      quality = audioQualities[1] // Среднее качество по умолчанию
    }
    
    // Адаптируем под сеть
    const useLowQualityAudio = effectiveType === 'slow-2g' || effectiveType === '2g'
    
    if (useLowQualityAudio && quality.id !== 'low') {
      const lowQuality = audioQualities[0] // Низкое качество
      const parts = currentTrack.audioUrl.split('.')
      const extension = parts.pop()
      return `${parts.join('.')}_low.${extension}`
    }
    
    // Для lossless качества проверяем поддержку браузера
    if (quality.id === 'lossless' && !audioRef.current?.canPlayType('audio/flac')) {
      const highQuality = audioQualities[2] // Высокое качество mp3
      const parts = currentTrack.audioUrl.split('.')
      const extension = parts.pop()
      return `${parts.join('.')}_high.${extension}`
    }
    
    return currentTrack.audioUrl
  }, [currentTrack, selectedQuality, effectiveType, audioQualities])

  // Функция предзагрузки аудио
  const preloadAudio = useCallback(async (track: unknown, quality: string) => {
    const cacheKey = `${track.id}_${quality}`
    
    if (audioCache[cacheKey]) {
      // Обновляем время последнего использования
      setAudioCache(prev => ({
        ...prev,
        [cacheKey]: {
          ...prev[cacheKey],
          lastUsed: Date.now()
        }
      }))
      return audioCache[cacheKey].audio
    }

    setIsPreloading(true)
    setPreloadProgress(0)

    return new Promise<HTMLAudioElement>((resolve, reject) => {
      const audio = new Audio()
      audio.crossOrigin = 'anonymous'
      audio.preload = 'auto'
      
      audio.addEventListener('loadstart', () => {
        setPreloadProgress(10)
      })
      
      audio.addEventListener('progress', (e) => {
        if (e.lengthComputable) {
          const progress = (e.loaded / e.total) * 90 + 10
          setPreloadProgress(progress)
        }
      })
      
      audio.addEventListener('canplaythrough', () => {
        setPreloadProgress(100)
        setIsPreloading(false)
        
        // Сохраняем в кэш
        setAudioCache(prev => ({
          ...prev,
          [cacheKey]: {
            audio,
            lastUsed: Date.now(),
            quality
          }
        }))
        
        resolve(audio)
      })
      
      audio.addEventListener('error', (e) => {
        setIsPreloading(false)
        reject(e)
      })
      
      audio.src = audioSrc()
    })
  }, [audioCache, audioSrc])

  // Функция очистки кэша
  const cleanupCache = useCallback(() => {
    const now = Date.now()
    const maxAge = 30 * 60 * 1000 // 30 минут
    const maxCacheSize = 10 // Максимум 10 треков в кэше
    
    setAudioCache(prev => {
      const entries = Object.entries(prev)
        .filter(([_, value]) => now - value.lastUsed < maxAge)
        .sort((a, b) => b[1].lastUsed - a[1].lastUsed)
        .slice(0, maxCacheSize)
      
      return Object.fromEntries(entries)
    })
  }, [])

  // Предзагрузка следующего трека
  useEffect(() => {
    if (queue.length > 0 && currentQueueIndex >= 0) {
      const nextIndex = currentQueueIndex + 1
      if (nextIndex < queue.length) {
        const nextTrack = queue[nextIndex]
        preloadAudio(nextTrack, selectedQuality)
      }
    }
  }, [queue, currentQueueIndex, selectedQuality, preloadAudio])

  // Очистка кэша каждые 5 минут
  useEffect(() => {
    const interval = setInterval(cleanupCache, 5 * 60 * 1000)
    return () => clearInterval(interval)
  }, [cleanupCache])

  // Загрузка плейлистов
  useEffect(() => {
    const loadPlaylists = async () => {
      try {
        const userPlaylists = await getUserPlaylists()
        setPlaylists(userPlaylists)
      } catch (error) {
        console.error('Error loading playlists:', error)
      }
    }
    loadPlaylists()
  }, [getUserPlaylists])

  // Эффекты для аудио
  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = isMuted ? 0 : volume / 100
    }
  }, [volume, isMuted])

  useEffect(() => {
    if (audioRef.current) {
      if (isPlaying) {
        audioRef.current.play().catch(e => console.error("Error playing audio:", e))
      } else {
        audioRef.current.pause()
      }
    }
  }, [isPlaying, currentTrack])

  // Обработчики событий
  const handleTimeUpdate = useCallback(() => {
    if (audioRef.current) {
      const time = audioRef.current.currentTime
      seekTo(time)
    }
  }, [seekTo])

  const handleLoadedMetadata = useCallback(() => {
    if (audioRef.current) {
      useAudioStore.getState().setDuration(audioRef.current.duration)
    }
  }, [])

  const handleSeek = useCallback((value: number[]) => {
    const newTime = value[0]
    seekTo(newTime)
    if (audioRef.current) {
      audioRef.current.currentTime = newTime
    }
  }, [seekTo])

  const handleVolumeChange = useCallback((value: number[]) => {
    const newVolume = value[0]
    setVolume(newVolume)
  }, [setVolume])

  const handleQueueItemClick = useCallback((track: unknown, index: number) => {
    play(track)
  }, [play])

  // Форматирование времени
  const formatQueueTime = useCallback((seconds: number) => {
    const minutes = Math.floor(seconds / 60)
    const remainingSeconds = Math.floor(seconds % 60)
    return `${minutes}:${remainingSeconds.toString().padStart(2, '0')}`
  }, [])

  // Форматирование чисел
  const formatNumber = useCallback((num: number) => {
    if (num >= 1000000) {
      return (num / 1000000).toFixed(1) + 'M'
    }
    if (num >= 1000) {
      return (num / 1000).toFixed(1) + 'K'
    }
    return num.toString()
  }, [])

  // Создание плейлиста
  const handleCreatePlaylist = useCallback(async () => {
    if (!newPlaylistName.trim()) return
    
    try {
      const playlist = await createPlaylist({
        name: newPlaylistName,
        description: newPlaylistDescription,
        isPublic: false
      })
      
      setPlaylists(prev => [...prev, playlist])
      setNewPlaylistName('')
      setNewPlaylistDescription('')
    } catch (error) {
      console.error('Error creating playlist:', error)
    }
  }, [newPlaylistName, newPlaylistDescription, createPlaylist])

  // Добавление в плейлист
  const handleAddToPlaylist = useCallback(async (playlistId: string) => {
    if (!currentTrack) return
    
    try {
      await addToPlaylist(playlistId, currentTrack)
      alert('Трек добавлен в плейлист')
    } catch (error) {
      console.error('Error adding to playlist:', error)
    }
  }, [currentTrack, addToPlaylist])

  // Применение пресета эквалайзера
  const applyEqualizerPreset = useCallback((preset: EqualizerPreset) => {
    setEqualizerSettings(preset.settings)
  }, [])

  // Если нет текущего трека, не отображаем плеер
  if (!currentTrack) {
    return null
  }

  return (
    <>
      <audio
        ref={audioRef}
        src={audioSrc()}
        onTimeUpdate={handleTimeUpdate}
        onLoadedMetadata={handleLoadedMetadata}
        onEnded={playNext}
        crossOrigin="anonymous"
        preload="auto"
      />
      
      {/* Основной плеер */}
      <Card className="fixed bottom-0 left-0 right-0 z-50 rounded-none border-t">
        <CardContent className="p-4">
          <div className="flex items-center space-x-4">
