            <span className="text-sm">Предзагрузка...</span>
            <div className="flex-1 bg-secondary rounded-full h-2">
              <div 
                className="bg-primary h-2 rounded-full transition-all duration-300"
                style={{ width: `${preloadProgress}%` }}
              />
            </div>
            <span className="text-xs text-muted-foreground">{Math.round(preloadProgress)}%</span>
          </div>
        </div>
      )}

      {/* Визуализатор аудио */}
      {showVisualizer && audioRef.current && (
        <div className="fixed bottom-20 left-4 right-4 z-40 bg-card border rounded-lg p-2">
