'use client'

import { useState, useEffect, useCallback } from 'react'
import { MainLayout } from '@/components/layout/main-layout'
import { Button, Input, Card, CardContent, CardDescription, CardHeader, CardTitle, Badge, Progress, Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui'
import { 
  TrendingUp, 
  DollarSign, 
  Clock, 
  Lock,
  Unlock,
  Calculator,
  AlertCircle,
  CheckCircle,
  Loader2,
  Star,
  Zap,
  Calendar,
  Target,
  Activity,
  BarChart3,
  PieChart,
  Shield,
  Rocket,
  Gift,
  Sparkles,
  TrendingDown,
  RefreshCw
} from '@/components/icons'
import { formatNumber } from '@/lib/utils'
import { InvisibleDeflationAdapter } from '../wallet/invisible-deflation-adapter';

interface StakingPool {
  id: string
  name: string
  type: 'fixed' | 'flexible' | 'liquidity' | 'nft' | 'tiered'
  apy: number
  minAmount: number
  maxAmount: number
  duration: number
  totalStaked: number
  participants: number
  isAvailable: boolean
  description: string
  riskLevel: 'low' | 'medium' | 'high'
  earlyWithdrawalPenalty: number
  compoundFrequency: 'daily' | 'weekly' | 'monthly'
  performanceFee: number
  bonus?: {
