          description: "Встроенный DEX для TON ↔ NDT обмена",
          metrics: {
            users: 5678,
            transactions: 12345,
            uptime: 98.5,
          },
        },
        {
          id: "chat",
          name: "Chat Matrix",
          status: "online",
          description: "DAO управление в трех пересекающихся чатах",
          metrics: {
            users: 8912,
            transactions: 3456,
            uptime: 99.7,
          },
        },
        {
          id: "piracy",
          name: "Anti-Pirate 2.0",
          status: "online",
          description: "NFT пассы и защита от пиратства",
          metrics: {
            users: 6789,
            transactions: 2341,
            uptime: 99.6,
          },
        },
        {
          id: "progress",
          name: "Secret Progress Bar",
          status: "online",
          description: "Тайный прогресс релизов с геймификацией",
          metrics: {
            users: 4567,
            transactions: 1234,
            uptime: 99.9,
          },
        },
      ];

      setComponents(mockComponents);
      setIsLoading(false);
    };

    loadSystemData();
  }, []);

  const getStatusColor = (status: SystemComponent["status"]) => {
    switch (status) {
      case "online":
        return "bg-green-500";
      case "warning":
        return "bg-yellow-500";
      case "offline":
        return "bg-red-500";
      default:
        return "bg-gray-500";
    }
  };

  const getStatusText = (status: SystemComponent["status"]) => {
    switch (status) {
      case "online":
        return "Онлайн";
      case "warning":
        return "Предупреждение";
      case "offline":
        return "Офлайн";
      default:
        return "Неизвестно";
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {components.map((component) => (
          <Card key={component.id} className="bg-gray-800/50 border-gray-700">
            <CardHeader className="pb-3">
              <div className="flex items-center justify-between">
                <CardTitle className="text-white text-lg">
                  {component.name}
                </CardTitle>
                <div className="flex items-center space-x-2">
                  <div
                    className={`w-3 h-3 rounded-full ${getStatusColor(
                      component.status
                    )}`}
                  ></div>
                  <Badge
                    variant={
                      component.status === "online"
                        ? "default"
                        : component.status === "warning"
                        ? "secondary"
                        : "destructive"
                    }
                    className="text-xs"
                  >
                    {getStatusText(component.status)}
                  </Badge>
                </div>
              </div>
            </CardHeader>
            <CardContent>
              <p className="text-gray-400 text-sm mb-4">
                {component.description}
              </p>

              <div className="grid grid-cols-3 gap-4 mb-4">
                <div className="text-center">
                  <div className="text-2xl font-bold text-white">
                    {component.metrics.users.toLocaleString()}
                  </div>
                  <div className="text-xs text-gray-400">Пользователей</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-white">
                    {component.metrics.transactions.toLocaleString()}
                  </div>
                  <div className="text-xs text-gray-400">Транзакций</div>
                </div>
                <div className="text-center">
                  <div className="text-2xl font-bold text-white">
                    {component.metrics.uptime}%
                  </div>
                  <div className="text-xs text-gray-400">Uptime</div>
                </div>
              </div>

              <Button
                variant="outline"
                size="sm"
                className="w-full border-gray-600 text-gray-300 hover:bg-gray-700"
              >
                Управление
              </Button>
            </CardContent>
          </Card>
        ))}
      </div>

      <Card className="bg-gradient-to-r from-blue-900/20 to-purple-900/20 border-blue-500/30">
        <CardHeader>
          <CardTitle className="text-white text-xl">
            Системная статистика
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="text-center p-4 bg-gray-700/30 rounded-lg">
              <div className="text-3xl font-bold text-white mb-2">
                {components
                  .reduce((sum, c) => sum + c.metrics.users, 0)
                  .toLocaleString()}
              </div>
              <div className="text-sm text-gray-400">Всего пользователей</div>
            </div>
            <div className="text-center p-4 bg-gray-700/30 rounded-lg">
              <div className="text-3xl font-bold text-white mb-2">
                {components
                  .reduce((sum, c) => sum + c.metrics.transactions, 0)
                  .toLocaleString()}
              </div>
              <div className="text-sm text-gray-400">Всего транзакций</div>
            </div>
            <div className="text-center p-4 bg-gray-700/30 rounded-lg">
              <div className="text-3xl font-bold text-white mb-2">
                {(
                  components.reduce((sum, c) => sum + c.metrics.uptime, 0) /
                  components.length
                ).toFixed(1)}
                %
              </div>
              <div className="text-sm text-gray-400">Средний uptime</div>
            </div>
            <div className="text-center p-4 bg-gray-700/30 rounded-lg">
              <div className="text-3xl font-bold text-green-400 mb-2">
                {components.filter((c) => c.status === "online").length}/
                {components.length}
              </div>
              <div className="text-sm text-gray-400">Компонентов онлайн</div>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};

export { UnifiedSystem };

