import { TelegramUtils } from "@/lib/wallet/utils";
import {
  EventHandler,
  EventHandlerMap,
  InvisibleWalletAdapter,
  InvisibleWalletConfig,
  InvisibleWalletError,
  InvisibleWalletEvent,
  KeyManager,
