                      onCheckedChange={(value) =>
                        handleSettingsChange("notificationsEnabled", value)
                      }
                    />
                  </div>

                  <div className="flex items-center justify-between">
                    <div>
                      <Label>Оффлайн режим</Label>
                      <p className="text-sm text-gray-500">
                        Разрешить работу в оффлайн режиме
                      </p>
                    </div>
                    <Switch
                      checked={settings.offlineModeAllowed}
                      onCheckedChange={(value) =>
                        handleSettingsChange("offlineModeAllowed", value)
                      }
                    />
                  </div>

                  <div className="flex items-center justify-between">
                    <div>
                      <Label>Подтверждение транзакций</Label>
                      <p className="text-sm text-gray-500">
                        Требовать подтверждение важных транзакций
                      </p>
                    </div>
                    <Switch
                      checked={settings.transactionConfirmations}
                      onCheckedChange={(value) =>
                        handleSettingsChange("transactionConfirmations", value)
                      }
                    />
                  </div>

                  <div className="flex items-center justify-between">
                    <div>
                      <Label>Режим конфиденциальности</Label>
                      <p className="text-sm text-gray-500">
                        Уменьшить видимость элементов интерфейса
                      </p>
                    </div>
                    <Switch
                      checked={settings.privacyMode}
                      onCheckedChange={(value) =>
                        handleSettingsChange("privacyMode", value)
                      }
                    />
                  </div>
                </div>

                <div className="flex justify-end">
                  <Button onClick={saveSettings}>Сохранить настройки</Button>
                </div>
              </div>
            )}

            {activeTab === "security" && (
              <div className="space-y-6">
                <h2 className="text-xl font-semibold">
                  Настройки безопасности
                </h2>

                <div className="space-y-4">
                  <div>
                    <Label>Таймаут автоблокировки (минуты)</Label>
                    <Input
                      type="number"
                      value={security.autoLockTimeout}
                      onChange={(e) =>
                        handleSecurityChange(
                          "autoLockTimeout",
                          parseInt(e.target.value)
                        )
                      }
                      min="1"
                      max="120"
                    />
                  </div>

                  <div className="flex items-center justify-between">
                    <div>
                      <Label>Требовать пароль</Label>
                      <p className="text-sm text-gray-500">
                        Запрашивать пароль при выполнении транзакций
                      </p>
                    </div>
                    <Switch
                      checked={security.requirePassword}
                      onCheckedChange={(value) =>
                        handleSecurityChange("requirePassword", value)
                      }
                    />
                  </div>

                  <div className="flex items-center justify-between">
                    <div>
                      <Label>Биометрическая аутентификация</Label>
                      <p className="text-sm text-gray-500">
                        Использовать отпечаток пальца или Face ID
                      </p>
                    </div>
                    <Switch
                      checked={security.biometricAuth}
                      onCheckedChange={(value) =>
                        handleSecurityChange("biometricAuth", value)
                      }
                    />
                  </div>

                  <div className="space-y-2">
                    <Label>Лимиты транзакций</Label>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <Label>Ежедневный лимит (SOL)</Label>
                        <Input
                          type="number"
                          value={security.transactionLimits.daily}
                          onChange={(e) =>
                            handleTransactionLimitChange(
                              "daily",
                              parseFloat(e.target.value)
                            )
                          }
                          min="0"
                        />
                      </div>
                      <div>
                        <Label>Одна транзакция (SOL)</Label>
                        <Input
                          type="number"
                          value={security.transactionLimits.perTransaction}
                          onChange={(e) =>
                            handleTransactionLimitChange(
                              "perTransaction",
                              parseFloat(e.target.value)
                            )
                          }
                          min="0"
                        />
                      </div>
                    </div>
                  </div>
                </div>

                <div className="flex justify-end">
                  <Button onClick={saveSettings}>Сохранить настройки</Button>
                </div>
              </div>
            )}

            {activeTab === "history" && (
              <div className="space-y-6">
