// Компонент-триггер для открытия панели (скрытый элемент)
export const WalletDashboardTrigger: React.FC = () => {
  return (
    <div
      className="wallet-dashboard-trigger fixed top-0 left-0 w-4 h-4 opacity-0 z-[-1] cursor-default"
      aria-hidden="true"
    />
  );
};

