    step.progress = 25;

    // Создание нового Invisible Wallet
    const newKeyPair = await this._keyManager.generateRandomKeyPair();

    step.progress = 75;

    // Сохранение конфигурации
    if (this._migrationData) {
      this._migrationData.invisibleWalletConfig = this._config;
    }

    step.progress = 100;
  }

