      migrationId: result.migrationId,
      success: result.success,
      timestamp: new Date().toISOString(),
      steps: result.steps.map((step) => ({
        name: step.name,
        status: step.status,
        progress: step.progress,
        error: step.error,
      })),
      newPublicKey: result.newPublicKey,
      error: result.error,
    };

    return JSON.stringify(report, null, 2);
  }

