  instructions: unknown[];
  signers?: unknown[];
  feePayer?: PublicKey;
  commitment?: "processed" | "confirmed" | "finalized";
}

// Хук для отправки транзакций
export function useTransactions() {
  const { connection } = useConnection();
  const { wallet } = useWallet();

