export const DEFAULT_CHAINALYSIS_CONFIG: Partial<ChainalysisConfig> = {
  environment: "SANDBOX", // Используем песочницу для разработки
  timeout: 30000, // 30 секунд
  retryAttempts: 3,
  retryDelay: 1000, // 1 секунда
  monitoringEnabled: true,
  riskThresholds: {
    LOW: 25,
    MEDIUM: 50,
    HIGH: 75,
