): "LOW" | "MEDIUM" | "HIGH" | "SEVERE" {
  const mapping =
    CHAINALYSIS_CATEGORY_RISK_MAPPING[
      category as keyof typeof CHAINALYSIS_CATEGORY_RISK_MAPPING
    ];
  return mapping?.risk || "MEDIUM";
}
