          sumsubApplicantId,
        },
        severity: "LOW",
      });

      const levelConfig =
        KYCSumsubService.VERIFICATION_LEVELS[request.verificationLevel];
      const mappedLevel = this.mapSumsubLevelToKYCLevel(
