  const highRiskCountries = ["AF", "IR", "KP", "MM", "SY", "VE", "YE", "ZW"];
  const mediumRiskCountries = ["BY", "CU", "CD", "IQ", "LR", "SD", "SS", "UA"];

  if (highRiskCountries.includes(countryCode)) {
