      sortBy = 'createdAt',
      sortOrder = 'desc'
    } = options

    return this.executeQuery(async () => {
      const where: Record<string, unknown> = {}
      
      if (genre) {
        where.genre = genre
      }
      
      if (artistId) {
        where.artistId = artistId
      }

      const orderBy: Record<string, unknown> = {}
      orderBy[sortBy] = sortOrder

      const tracks = await this.prisma.track.findMany({
        where,
        orderBy,
        skip: offset,
        take: limit,
        include: {
          artist: {
            select: {
              id: true,
              username: true,
              avatar: true
            }
          },
          _count: {
            select: {
              likes: true,
              comments: true,
              playHistory: true
            }
          }
        }
      })

      // Кеширование результата (в реальном приложении здесь будет сохранение в Redis/кеш)
      // await this.setCache(cacheKey, tracks, { ttl: 300 }) // 5 минут

      return tracks
    }, 'getTracksWithCache', [options])
  }

  /**
   * Оптимизированный запрос для получения истории прослушиваний
