        },
        include: {
          artist: {
            select: {
              id: true,
              username: true,
              avatar: true
            }
          },
          _count: {
            select: {
              likes: true,
              playHistory: true
            }
          }
        },
        orderBy: [
          { playCount: 'desc' },
          { likeCount: 'desc' }
        ],
        take: limit
      })

      // Кеширование
      // await this.setCache(cacheKey, recommendations, { ttl: 1800 }) // 30 минут

      return recommendations
    }, 'getRecommendations', [userId, limit])
  }

  /**
