describe("Prisma Sharding Module", () => {
  let config: ShardingConfig;
  let connectionStrings: string[];

  beforeEach(() => {
    config = {
      ...DEFAULT_SHARDING_CONFIG,
      enabled: true,
      shardCount: 3,
      defaultShard: 0,
      strategy: "user_id",
    };

    connectionStrings = [
      "file:./shard0.db",
      "file:./shard1.db",
      "file:./shard2.db",
    ];
  });

