      })),
      startDate: new Date().toISOString(),
      lastHarvest: new Date().toISOString(),
      apy: farm.apy,
      currentValue: 0
    }

    // 3. Передача токенов в ферму
    await this.depositToFarm(farmId, position.id, deposits)

    return position
  }

