  role: 'ARTIST' | 'PRODUCER' | 'LABEL' | 'PUBLISHER' | 'DISTRIBUTOR' | 'FAN'
  profileData: {
    name: string
    bio: string
    avatar: string
    socialLinks: Record<string, string>
    achievements: Achievement[]
  }
  credentials: Credential[]
  reputation: {
