  const helia = await getHelia()
  const fs = unixfs(helia)
  
  const data = file instanceof File ? new Uint8Array(await file.arrayBuffer()) : file
  const cid = await fs.addBytes(data)
  
  return { cid: cid.toString(), size: data.length }
}

