  const helia = await getHelia()
  const fs = unixfs(helia)
  
  const chunks = []
  for await (const chunk of fs.cat(cid)) {
    chunks.push(chunk)
  }
  
  return new Uint8Array(chunks.reduce((acc, chunk) => [...acc, ...chunk], []))
} getHelia uploadToIPFS downloadFromIPFS

