    let error: Error | null = null;

    try {
      result = operation();
    } catch (e) {
      error = e as Error;
    }

    const endTime = performance.now();

    if (error) {
      this.recordMetric({
        responseTime: endTime - startTime,
        timestamp: Date.now(),
        endpoint: context,
        method: "sync",
        statusCode: 500,
        error: error.message,
