    if (success) {
      loadNotifications()
    }
    return success
  }, [userId, loadNotifications])

  const markAllAsRead = useCallback(async () => {
    const count = await notificationSystem.markAllAsRead(userId)
    loadNotifications()
    return count
  }, [userId, loadNotifications])

  const deleteNotification = useCallback(async (notificationId: string) => {
    const success = await notificationSystem.deleteNotification(notificationId, userId)
    if (success) {
      loadNotifications()
    }
    return success
  }, [userId, loadNotifications])

  const updateSettings = useCallback(async (newSettings: Partial<NotificationSettings>) => {
    const updated = await notificationSystem.updateNotificationSettings(userId, newSettings)
    setSettings(updated)
    return updated
  }, [userId])

  return {
    notifications,
    unreadCount,
    settings,
    loading,
    loadNotifications,
    markAsRead,
    markAllAsRead,
    deleteNotification,
    updateSettings
  }
}

export default NotificationSystem

