/* Qdrant service with local filesystem fallback.
   - If QDRANT_URL and QDRANT_API_KEY are set, uses remote Qdrant.
   - Otherwise, falls back to a local JSON-backed store to allow offline indexing/search.

   Local store layout:
     <project_root>/db/qdrant/<collection>.json
   Data format:
     [
       {
         "id": "string",
         "vector": number[],
         "payload": {
           "content": "string",
           "metadata": { ... }
         }
       },
       ...
     ]
*/

import fs from "fs/promises";
import path from "path";

// Interfaces
interface QdrantDocument {
  id: string;
  content: string;
  metadata: Record<string, any>;
  vector: number[];
}

type QdrantSearchResult = {
  id: string | number;
  score: number;
  payload?: {
    content?: string;
    metadata?: Record<string, any>;
    [key: string]: any;
  };
};

// Local point representation
interface LocalPoint {
  id: string;
  vector: number[];
  payload: {
    content: string;
    metadata: Record<string, any>;
  };
}

// Service
class QdrantService {
  private collectionName = "codedocs";

  // Lazy-initialized client (remote), or null if unavailable
  private clientPromise?: Promise<any | null>;

  // Determine if remote Qdrant env is available
  private hasQdrantEnv(): boolean {
    return Boolean(process.env.QDRANT_URL && process.env.QDRANT_API_KEY);
  }

  // Lazily import qdrant-config to avoid top-level throw when env is missing
  private async getClient(): Promise<any | null> {
    if (this.clientPromise) return this.clientPromise;

    if (!this.hasQdrantEnv()) {
      this.clientPromise = Promise.resolve(null);
      return this.clientPromise;
    }

    this.clientPromise = import("./qdrant-config")
      .then((mod) => mod.default)
      .catch((err) => {
        console.warn(
          "[QdrantService] Failed to initialize remote Qdrant client, using local fallback:",
          err?.message || err,
        );
        return null;
      });

    return this.clientPromise;
  }

  // Public API

  async initCollection() {
    const client = await this.getClient();

    if (client) {
      // Remote Qdrant
      try {
        const collections = await client.getCollections();
        const exists = collections.collections?.some(
          (c: any) => c.name === this.collectionName,
        );

        if (!exists) {
          await client.createCollection(this.collectionName, {
            vectors: {
              size: 512,
              distance: "Cosine",
            },
          });
          console.log(
            `[QdrantService] Collection ${this.collectionName} created (remote).`,
          );
        } else {
          console.log(
            `[QdrantService] Collection ${this.collectionName} already exists (remote).`,
          );
        }

        return;
      } catch (err) {
        console.warn(
          "[QdrantService] Remote initCollection failed, falling back to local store:",
          err?.message || err,
        );
      }
    }

    // Local fallback
    await this.ensureLocalStore();
    console.log(
      `[QdrantService] Collection ${this.collectionName} available (local fallback).`,
    );
  }

  async addDocument(document: QdrantDocument) {
    const client = await this.getClient();

    if (client) {
      // Remote Qdrant
      try {
        const points = [
          {
            id: document.id,
            vector: document.vector,
            payload: {
              content: document.content,
              metadata: document.metadata,
            },
          },
        ];

        await client.upsert(this.collectionName, { points });
        console.log(
          `[QdrantService] Document ${document.id} upserted (remote).`,
        );
        return;
      } catch (err) {
        console.warn(
          `[QdrantService] Remote addDocument failed for ${document.id}, falling back to local store:`,
          err?.message || err,
        );
      }
    }

    // Local fallback
    await this.ensureLocalStore();
    const points = await this.readLocalPoints();

    const idx = points.findIndex((p) => p.id === document.id);
    const localPoint: LocalPoint = {
      id: document.id,
      vector: document.vector,
      payload: {
        content: document.content,
        metadata: document.metadata,
      },
    };

    if (idx >= 0) {
      points[idx] = localPoint;
    } else {
      points.push(localPoint);
    }

    await this.writeLocalPoints(points);
    console.log(`[QdrantService] Document ${document.id} upserted (local).`);
  }

  async searchDocuments(
    queryVector: number[],
    limit: number = 5,
  ): Promise<QdrantSearchResult[]> {
    const client = await this.getClient();

    if (client) {
      // Remote Qdrant
      try {
        const results = await client.search(this.collectionName, {
          vector: queryVector,
          limit: limit,
          with_payload: true,
        });

        return results;
      } catch (err) {
        console.warn(
          "[QdrantService] Remote search failed, falling back to local store:",
          err?.message || err,
        );
      }
    }

    // Local fallback
    await this.ensureLocalStore();
    const points = await this.readLocalPoints();

    // Compute cosine similarity
    const scored: QdrantSearchResult[] = points
      .map((p) => ({
        id: p.id,
        score: this.cosineSimilarity(queryVector, p.vector),
        payload: {
          content: p.payload.content,
          metadata: p.payload.metadata,
        },
      }))
      .sort((a, b) => b.score - a.score)
      .slice(0, limit);

    return scored;
  }

  async searchDocumentsByContent(
    content: string,
    limit: number = 5,
  ): Promise<QdrantSearchResult[]> {
    // In a real implementation, you would convert content into an embedding vector.
    // For parity with existing code, we generate a mock vector and reuse searchDocuments
    const mockVector = this.randomVector(512);
    return this.searchDocuments(mockVector, limit);
  }

  // Local store helpers

  private get localDir(): string {
    return path.join(process.cwd(), "db", "qdrant");
  }

  private get localFile(): string {
    return path.join(this.localDir, `${this.collectionName}.json`);
  }

  private async ensureLocalStore() {
    try {
      await fs.mkdir(this.localDir, { recursive: true });
      try {
        await fs.access(this.localFile);
      } catch {
        // Initialize empty collection file
        await fs.writeFile(this.localFile, "[]", "utf-8");
      }
    } catch (err) {
      console.error(
        "[QdrantService] Failed to ensure local store directory or file:",
        err?.message || err,
      );
      throw err;
    }
  }

  private async readLocalPoints(): Promise<LocalPoint[]> {
    try {
      const raw = await fs.readFile(this.localFile, "utf-8");
      const data = JSON.parse(raw);
      if (Array.isArray(data)) return data as LocalPoint[];
      return [];
    } catch (err) {
      console.warn(
        "[QdrantService] Failed to read local points, reinitializing store:",
        err?.message || err,
      );
      await this.writeLocalPoints([]);
      return [];
    }
  }

  private async writeLocalPoints(points: LocalPoint[]) {
    const tmpFile = `${this.localFile}.tmp`;
    const json = JSON.stringify(points, null, 2);
    await fs.writeFile(tmpFile, json, "utf-8");
    await fs.rename(tmpFile, this.localFile);
  }

  // Math helpers

  private cosineSimilarity(a: number[], b: number[]): number {
    if (a.length !== b.length || a.length === 0) return 0;

    let dot = 0;
    let normA = 0;
    let normB = 0;

    for (let i = 0; i < a.length; i++) {
      const av = a[i] ?? 0;
      const bv = b[i] ?? 0;
      dot += av * bv;
      normA += av * av;
      normB += bv * bv;
    }

    if (normA === 0 || normB === 0) return 0;
    // Map cosine from [-1, 1] to [0, 1] to resemble "score"
    const cos = dot / (Math.sqrt(normA) * Math.sqrt(normB));
    return (cos + 1) / 2;
  }

  private randomVector(size: number): number[] {
    // NOTE: Placeholder for embedding generation, aligns with existing mock approach
    return Array(size)
      .fill(0)
      .map(() => Math.random());
  }
}

export default new QdrantService();
