 */
export interface OFACMessage {
  header: {
    version: string;
    timestamp: string;
    messageId: string;
    priority: "LOW" | "MEDIUM" | "HIGH" | "URGENT";
  };
  screeningRequest: {
    entities: Array<{
      type: "INDIVIDUAL" | "ENTITY";
