      aliases?: string[];
      dateOfBirth?: string;
      nationality?: string;
      addresses?: string[];
      identificationNumbers?: string[];
      additionalInfo?: Record<string, any>;
    }>;
    transaction: {
      id: string;
      amount: number;
      currency: string;
      date: string;
      parties: Array<{
        type: "ORIGINATOR" | "BENEFICIARY";
        name: string;
        address?: string;
        accountNumber?: string;
      }>;
    };
  };
  response?: {
    matches: Array<{
      entity: {
        name: string;
        type: string;
        list: string;
        score: number;
      };
      confidence: number;
      details: string;
    }>;
    recommendation: "APPROVE" | "REVIEW" | "BLOCK";
    processedAt: string;
  };
}

// ============================================================================
// VASP реестр и конфигурация
// ============================================================================

/**
 * Запись в реестре VASP
 */
export interface VASPRegistryEntry {
  id: string;
  vaspInfo: VASPInfo;
  technicalEndpoints: {
    travelRuleEndpoint: string;
    ivms101Endpoint?: string;
    catEndpoint?: string;
    ofacEndpoint?: string;
    backupEndpoints?: string[];
  };
  supportedProtocols: string[]; // ["IVMS101", "CAT", "OFAC", etc.]
  supportedFormats: string[]; // ["JSON", "XML", etc.]
  encryptionKeys: Array<{
    keyId: string;
    algorithm: string;
    publicKey: string;
    validFrom: string;
    validUntil?: string;
  }>;
  status: "ACTIVE" | "INACTIVE" | "SUSPENDED";
  lastVerified: string;
  reputation: {
    score: number; // 0-100
    reviews: number;
    lastIncident?: string;
  };
}

/**
