    const totalFees = breakdowns.reduce((sum, breakdown) => sum + breakdown.feeAmount, 0);
    const totalNetAmount = breakdowns.reduce((sum, breakdown) => sum + breakdown.netAmount, 0);
    
    return {
      totalBurned: Math.round(totalBurned * 100) / 100,
