      );
    }

    // Validate file name
    const fileName = file.name;
    if (
      fileName.includes("../") ||
      fileName.includes("..\\") ||
      fileName.includes("..%2f") ||
      fileName.includes("..%5c")
    ) {
      throw new Error("Invalid file name");
    }

    // Validate file extension
