      ".bat",
      ".cmd",
      ".com",
      ".pif",
      ".scr",
      ".vbs",
      ".js",
      ".jar",
      ".sh",
      ".php",
      ".pl",
      ".py",
    ];
    const fileExtension = fileName
      .substring(fileName.lastIndexOf("."))
      .toLowerCase();
    if (dangerousExtensions.includes(fileExtension)) {
      throw new Error(`Dangerous file extension: ${fileExtension}`);
    }

    // Return mock result
    return {
      cid: "QmTestCID123",
      size: file.size,
      timestamp: new Date(),
      metadata,
